16	export const DEEPSEEK_CHAT_MODELS = [
17	  {
18	    id: 'deepseek-chat',
19	    cost: {
20	      input: 0.28 / 1e6,
21	      output: 0.42 / 1e6,
22	      cache_read: 0.028 / 1e6,
