import logger from '../logger';
import { parseChatPrompt, REQUEST_TIMEOUT_MS } from './shared';

import type {
  ApiProvider,
  CallApiContextParams,
  CallApiOptionsParams,
  ProviderOptions,
  ProviderResponse,
} from '../types/index';

const ABLITERATION_DEFAULT_API_BASE_URL = 'https://api.abliteration.ai/v1';
const ABLITERATION_DEFAULT_API_KEY_ENVAR = 'ABLIT_KEY';

interface AbliterationConfig {
  apiBaseUrl: string;
  apiKeyEnvar: string;
  showThinking: boolean;
  apiKey?: string;
  headers?: Record<string, string>;
  [key: string]: unknown;
}

type EnvMap = Record<string, string | undefined>;

/**
 * Returns the first candidate that is a non-empty string, treating empty
 * strings (and undefined) as "unset" so resolution falls through to the
 * next priority level.
 */
function firstNonEmpty(...candidates: Array<string | undefined>): string | undefined {
  for (const candidate of candidates) {
    if (typeof candidate === 'string' && candidate.trim() !== '') {
      return candidate;
    }
  }
  return undefined;
}

/**
 * Provider for the Abliteration AI service. Uses an OpenAI-compatible
 * chat/completions API but resolves its own authentication and base URL and
 * never falls back to OpenAI credentials or organization headers.
 */
export class AbliterationProvider implements ApiProvider {
  modelName: string;
  config: AbliterationConfig;
  env?: EnvMap;

  // The apiBaseUrl explicitly provided via constructor config (if any). Kept
  // separate so environment overrides can take precedence over the baked-in
  // default while still honoring an explicit constructor value.
  private readonly configuredApiBaseUrl?: string;

  constructor(modelName: string, options: ProviderOptions = {}) {
    const { config, id, env } = options;
    this.modelName = modelName;
    this.env = env as EnvMap | undefined;
    this.configuredApiBaseUrl = config?.apiBaseUrl;

    this.config = {
      ...config,
      apiBaseUrl: this.getApiUrl(),
      apiKeyEnvar: config?.apiKeyEnvar || ABLITERATION_DEFAULT_API_KEY_ENVAR,
      showThinking: config?.showThinking ?? false,
    };

    if (id) {
      this.id = () => id;
    }
  }

  id(): string {
    return `abliteration:${this.modelName}`;
  }

  toString(): string {
    return `[Abliteration Provider ${this.modelName}]`;
  }

  toJSON() {
    return {
      provider: 'abliteration' as const,
      model: this.modelName,
      config: {
        apiBaseUrl: this.getApiUrl(),
        // apiKey is always redacted from serialized output.
        apiKey: undefined,
        apiKeyEnvar: this.config.apiKeyEnvar,
        showThinking: this.config.showThinking,
      },
    };
  }

  /**
   * Resolves the API base URL in priority order (highest wins):
   * 1. config.apiBaseUrl passed in constructor options
   * 2. providerOptions.env.ABLIT_API_BASE_URL
   * 3. process.env.ABLIT_API_BASE_URL
   * 4. the default base URL
   * Empty strings are treated as unset.
   */
  getApiUrl(): string {
    return (
      firstNonEmpty(
        this.configuredApiBaseUrl,
        this.env?.ABLIT_API_BASE_URL,
        process.env.ABLIT_API_BASE_URL,
      ) ?? ABLITERATION_DEFAULT_API_BASE_URL
    );
  }

  /**
   * Resolves the API key in priority order:
   * 1. config.apiKey from constructor options
   * 2. env.ABLIT_KEY from providerOptions.env
   * 3. process.env.ABLIT_KEY
   * Never falls back to OPENAI_API_KEY.
   */
  getApiKey(): string | undefined {
    const envar = this.config.apiKeyEnvar || ABLITERATION_DEFAULT_API_KEY_ENVAR;
    return firstNonEmpty(this.config.apiKey, this.env?.[envar], process.env[envar]);
  }

  /**
   * Abliteration does not use organization headers.
   */
  getOrganization(): undefined {
    return undefined;
  }

  async callApi(
    prompt: string,
    context?: CallApiContextParams,
    _callApiOptions?: CallApiOptionsParams,
  ): Promise<ProviderResponse> {
    const apiKey = this.getApiKey();
    if (!apiKey) {
      throw new Error(
        'API key is not set. Set the ABLIT_KEY environment variable or add `apiKey` to the provider config.',
      );
    }

    const config = {
      ...this.config,
      ...context?.prompt?.config,
    };

    const messages = parseChatPrompt(prompt, [{ role: 'user', content: prompt }]);
    const body = {
      model: this.modelName,
      messages,
      ...(config.passthrough || {}),
    };

    const url = `${this.getApiUrl()}/chat/completions`;

    let data: any;
    let status: number;
    let statusText: string;
    let cached = false;
    let latencyMs: number | undefined;
    let responseHeaders: Record<string, string> | undefined;
    let deleteFromCache: (() => Promise<void>) | undefined;

    try {
      ({
        data,
        cached,
        status,
        statusText,
        latencyMs,
        headers: responseHeaders,
        deleteFromCache,
      } = await fetchWithCache(
        url,
        {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            Authorization: `Bearer ${apiKey}`,
            ...(config.headers || {}),
          },
          body: JSON.stringify(body),
        },
        REQUEST_TIMEOUT_MS,
        'json',
        context?.bustCache ?? context?.debug,
        (this.config as any).maxRetries,
      ));
    } catch (err) {
      logger.error(`Abliteration API call error: ${String(err)}`);
      return {
        error: `API call error: ${String(err)}`,
      };
    }

    if (status < 200 || status >= 300) {
      return {
        error: `API error: ${status} ${statusText}`,
        metadata: {
          http: {
            status,
            // Rate limit responses carry retry information in the headers.
            ...(status === 429 ? { headers: responseHeaders ?? {} } : {}),
          },
        },
      };
    }

    try {
      const message = data.choices[0].message;
      const content: string = message.content ?? '';

      let output = content;
      if (message.reasoning_content && this.config.showThinking) {
        output = `Thinking: ${message.reasoning_content}\n\n${content}`;
      }

      const usage = data.usage || {};

      return {
        output,
        tokenUsage: {
          total: usage.total_tokens,
          prompt: usage.prompt_tokens,
          completion: usage.completion_tokens,
          numRequests: 1,
        },
        cached,
        ...(latencyMs === undefined ? {} : { latencyMs }),
      };
    } catch (err) {
      await deleteFromCache?.();
      return {
        error: `API error: ${String(err)}: ${JSON.stringify(data)}`,
      };
    }
  }
}

/**
 * Factory that parses an 'abliteration:<model_name>' or
 * 'abliteration:chat:<model_name>' string and returns an AbliterationProvider.
 * The 'chat:' segment is treated as an alias and stripped from the id.
 */
export function createAbliterationProvider(
  providerPath: string,
  providerOptions: ProviderOptions = {},
): AbliterationProvider {
  const splits = providerPath.split(':');
  // splits[0] === 'abliteration'
  let modelParts = splits.slice(1);
  if (modelParts[0] === 'chat') {
    modelParts = modelParts.slice(1);
  }
  const modelName = modelParts.join(':');

  if (!modelName) {
    throw new Error(
      'Abliteration provider requires a model name. Use format: abliteration:<model_name> or abliteration:chat:<model_name>',
    );
  }

  return new AbliterationProvider(modelName, providerOptions);
}
